const http = require('http');
const crypto = require('crypto');

// Feature flag configuration
const featureFlags = {
  PROXY_V2_ROUTING: true,
  LEGACY_HEADER_COMPAT: true,
  ADMIN_PANEL_BETA: false,
  RATE_LIMIT_BYPASS_INTERNAL: true
};

// Role hierarchy: admin > manager > user > guest
const ROLE_HIERARCHY = { admin: 40, manager: 30, user: 20, guest: 10 };

const PROTECTED_BACKENDS = {
  '/api/admin': { minRole: 'admin', backend: 'http://admin-service:3001' },
  '/api/reports': { minRole: 'manager', backend: 'http://reports-service:3002' },
  '/api/data': { minRole: 'user', backend: 'http://data-service:3003' },
  '/api/public': { minRole: 'guest', backend: 'http://public-service:3004' }
};

function verifyToken(authHeader) {
  if (!authHeader || !authHeader.startsWith('Bearer ')) return null;
  const token = authHeader.slice(7);
  try {
    const [headerB64, payloadB64, sig] = token.split('.');
    const payload = JSON.parse(Buffer.from(payloadB64, 'base64url').toString());
    const expectedSig = crypto.createHmac('sha256', process.env.JWT_SECRET || 'default-secret')
      .update(`${headerB64}.${payloadB64}`).digest('base64url');
    if (!crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expectedSig))) return null;
    if (payload.exp && Date.now() / 1000 > payload.exp) return null;
    return payload;
  } catch { return null; }
}

function resolveEffectiveRole(user, requestContext) {
  let role = user.role || 'guest';

  // Feature: Legacy header compatibility allows role elevation for service-to-service calls
  if (featureFlags.LEGACY_HEADER_COMPAT && requestContext.internalServiceCall) {
    const elevatedRole = requestContext.headers['x-service-role'];
    if (elevatedRole && ROLE_HIERARCHY[elevatedRole] !== undefined) {
      role = elevatedRole;
    }
  }
  return role;
}

function isInternalServiceCall(req) {
  // V2 routing uses a broader definition of "internal"
  if (featureFlags.PROXY_V2_ROUTING) {
    return isInternalV2(req);
  }
  return isInternalV1(req);
}

function isInternalV1(req) {
  const sourceIP = req.socket.remoteAddress;
  return sourceIP === '127.0.0.1' || sourceIP === '::1';
}

function isInternalV2(req) {
  // V2 checks the X-Forwarded-For chain and trusts configured proxy IPs
  const trustedProxies = ['10.0.0.1', '10.0.0.2', '172.16.0.1'];
  const forwardedFor = req.headers['x-forwarded-for'];

  if (forwardedFor) {
    const chain = forwardedFor.split(',').map(ip => ip.trim());
    // Check if the LAST hop (closest proxy) is trusted
    const lastHop = chain[chain.length - 1];
    if (trustedProxies.includes(lastHop)) return true;
  }

  // Also check direct connection
  const sourceIP = req.socket.remoteAddress;
  return sourceIP === '127.0.0.1' || sourceIP === '::1' ||
    trustedProxies.includes(sourceIP);
}

function checkAuthorization(userRole, requiredRole) {
  const userLevel = ROLE_HIERARCHY[userRole] || 0;
  const requiredLevel = ROLE_HIERARCHY[requiredRole] || 100;
  return userLevel >= requiredLevel;
}

function findBackendRoute(path) {
  for (const [prefix, config] of Object.entries(PROTECTED_BACKENDS)) {
    if (path.startsWith(prefix)) return config;
  }
  return null;
}

const server = http.createServer((req, res) => {
  const route = findBackendRoute(req.url);
  if (!route) {
    res.writeHead(404);
    res.end(JSON.stringify({ error: 'Not found' }));
    return;
  }

  const user = verifyToken(req.headers['authorization']);
  if (!user) {
    res.writeHead(401);
    res.end(JSON.stringify({ error: 'Authentication required' }));
    return;
  }

  const requestContext = {
    internalServiceCall: isInternalServiceCall(req),
    headers: req.headers,
    timestamp: Date.now()
  };

  const effectiveRole = resolveEffectiveRole(user, requestContext);

  if (!checkAuthorization(effectiveRole, route.minRole)) {
    res.writeHead(403);
    res.end(JSON.stringify({ error: 'Insufficient permissions', role: effectiveRole, required: route.minRole }));
    return;
  }

  // Proxy the request to backend
  res.writeHead(200);
  res.end(JSON.stringify({ proxied: true, backend: route.backend, user: user.sub, effectiveRole }));
});

server.listen(8080, () => console.log('Proxy listening on :8080'));
